mapper.select:
select
   a.id,a.code,a.name,a.type,a.status,a.post,a.check_time,a.create_name,a.create_time,
  ( case  a.status when 0  then   '已创建' when 1  then   '执行中'  when 2  then   '已完成' when 3  then   '已关闭'
     when 4  then   '已归档'	  else '' end ) AS statusName,a.check_area
from wms_check_order a
where  1=1

    and a.code like CONCAT('%',#{form.code},'%')


    and a.name like CONCAT('%',#{form.name},'%')



        #{type}




        #{status}



    and a.id in (select check_order_id from wms_check_order_info where batch like CONCAT('%',#{form.batch},'%'))


    and a.id in (select check_order_id from wms_check_order_info where case_no like CONCAT('%',#{form.caseNo},'%'))


    and a.create_name like CONCAT('%',#{form.createName},'%')


    and a.id in (select check_order_id from wms_check_order_info where check_name like CONCAT('%',#{form.checkName},'%'))


    and DATE_FORMAT(a.create_time,'%Y-%m-%d' )  >=  #{form.beginCreateTime}
    and DATE_FORMAT(a.create_time,'%Y-%m-%d' )  <=  #{form.endCreateTime}


    and DATE_FORMAT(a.check_time,'%Y-%m-%d' )  >=  #{form.beginCheckTime}
    and DATE_FORMAT(a.check_time,'%Y-%m-%d' )  <=  #{form.endCheckTime}

order by a.create_time desc

select
a.id,a.code,a.name,a.type,a.status,a.post,a.check_time,a.create_name,a.create_time,a.check_area,
( case  a.status when 0  then   '已创建' when 1  then   '执行中'  when 2  then   '已完成' when 3  then   '已关闭'
when 4  then   '已归档' else '' end ) AS statusName
from wms_check_order a
where a.del_flag = 0

    and a.status = #{status}


    and a.post = #{post}


    and  a.create_time  >=  #{beginTime}
    and  a.create_time  <=  #{endTime}

order by a.create_time desc
